/**
 * Amount of Biologically Active Substance
 * 
 * "Amount of Biologically Active Substance" is the quantity of a substance expressed in
 *     International Units (IU), a measure of biological activity. It is dimensioned as mass (M) and organized under
 *     Mass Equivalent rather than as amount of substance (N): for any given substance one IU corresponds to a defined
 *     mass of an international reference preparation, so the quantity is a substance-dependent mass equivalent whose
 *     conversion factor is fixed per substance and resolved at the quantity level. It is deliberately not dimensioned
 *     as amount of substance, since one IU is not a fixed number of moles.
 *
 * http://qudt.org/vocab/quantitykind/AmountOfBiologicallyActiveSubstance
 */
export const AmountOfBiologicallyActiveSubstance: OtherIndividual = 'http://qudt.org/vocab/quantitykind/AmountOfBiologicallyActiveSubstance';

/**
 * Mass Equivalent
 * 
 * 
 *
 * http://qudt.org/vocab/quantitykind/MassEquivalent
 */
export const MassEquivalent: OtherIndividual = 'http://qudt.org/vocab/quantitykind/MassEquivalent';

/**
 * Amount of Biologically Active Substance per Mass
 * 
 * "Amount of Biologically Active Substance per Mass" is the biological activity of a preparation, expressed in
 *     International Units (IU), divided by its mass, as in IU/mg. Pharmacology calls this the potency of a preparation.
 *     Since the IU is dimensioned as a mass equivalent (see quantitykind:AmountOfBiologicallyActiveSubstance), the
 *     quantity is dimensionless and is organized under Mass Fraction. It is not commensurable with a plain mass
 *     fraction, because the mass that one IU corresponds to depends on the substance and is resolved at the quantity
 *     level. Not to be confused with Specific Activity, the radioactivity of a material per unit mass.
 *
 * http://qudt.org/vocab/quantitykind/AmountOfBiologicallyActiveSubstancePerMass
 */
export const AmountOfBiologicallyActiveSubstancePerMass: OtherIndividual = 'http://qudt.org/vocab/quantitykind/AmountOfBiologicallyActiveSubstancePerMass';

