/**
 * Amount of Data
 * 
 * The total quantity of digital information or storage, counted as a number of bits or bytes (and their SI
 *     and binary multiples). This is an abstract umbrella kind; its concrete specialisations are counted in bits
 *     (quantitykind:BitDataVolume) or bytes (quantitykind:ByteDataVolume). It is a counting quantity, distinct from the
 *     information-theoretic entropy carried by that data (see unit:SHANNON).
 *   
 *
 * http://qudt.org/vocab/quantitykind/AmountOfData
 */
export const AmountOfData: OtherIndividual = 'http://qudt.org/vocab/quantitykind/AmountOfData';

