export const Count: OtherIndividual = 'http://qudt.org/vocab/quantitykind/Count';

/**
 * Amount of Osmotically Active Entities
 * 
 * "Amount of Osmotically Active Entities" is an amount of substance in which the entities counted
 *     are the dissolved particles that act on osmotic pressure, measured in osmoles. It is organized under Amount of
 *     Substance but is not commensurable with it: one mole of a solute gives as many osmoles as the particles it
 *     dissociates into (1 mol of glucose gives 1 osmol, 1 mol of sodium chloride about 2), corrected by its osmotic
 *     coefficient. Those factors belong to the solute, so the conversion is resolved at the level of a concrete
 *     quantity.
 *
 * http://qudt.org/vocab/quantitykind/AmountOfOsmoticallyActiveEntities
 */
export const AmountOfOsmoticallyActiveEntities: OtherIndividual = 'http://qudt.org/vocab/quantitykind/AmountOfOsmoticallyActiveEntities';

